type MockWarehouse struct{ mock.Mock }

func (m *MockWarehouse) HasInventory(sku string, qty int) bool {
    return m.Called(sku, qty).Bool(0)
}

func TestOrderFills(t *testing.T) {
    wh := new(MockWarehouse)
    wh.On("HasInventory", "Talisker", 50).Return(true)
    wh.On("Remove", "Talisker", 50).Return()

    _ = NewOrder("Talisker", 50).Fill(wh)
    wh.AssertExpectations(t)
}
